def distance(latitude_1: float, longitude_1: float, elevation_1: Optional[
    float], latitude_2: float, longitude_2: float, elevation_2: Optional[
    float], haversine: bool=False) ->float:
    d_2d = haversine_distance(latitude_1, longitude_1, latitude_2, longitude_2) if haversine else (mod_math.sqrt((latitude_2 - latitude_1) ** 2 + (longitude_2 - longitude_1) ** 2) * ONE_DEGREE)

    if elevation_1 is None or elevation_2 is None:
        return d_2d

    d_elevation = elevation_2 - elevation_1
    return mod_math.sqrt(d_2d ** 2 + d_elevation ** 2)

def distance_2d(self, location: 'Location') ->Optional[float]:
    if not location:
        return None
    return distance(self.latitude, self.longitude, None, location.latitude, location.longitude, None)

