def parse_time(string: str) ->Optional[mod_datetime.datetime]:
    match = RE_TIMESTAMP.match(string)
    if not match:
        return None

    year, month, day, hour, minute, second, microsecond_str, tz_str = match.groups()

    year = int(year)
    month = int(month)
    day = int(day)
    hour = int(hour)
    minute = int(minute)
    second = int(second)

