        if len(microsecond_str) <= 6:
            microsecond = int(microsecond_str.ljust(6, '0'))
        else:
            microsecond = int(microsecond_str[:6])
            if len(microsecond_str) > 6 and int(microsecond_str[6]) >= 5:
                microsecond += 1
            if microsecond >= 1000000:
                microsecond = 999999

    tz = None
    if tz_str:
        if tz_str == 'Z':
            tz = SimpleTZ()
        else:
            tz = SimpleTZ(tz_str)

    return mod_datetime.datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tz)


