def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if not prettyprint:
        indent = ''

    fields = []
    if hasattr(instance, 'gpx_10_fields'):
        fields.extend(instance.gpx_10_fields)
    if hasattr(instance, 'gpx_11_fields'):
        fields.extend(instance.gpx_11_fields)

    attributes = []
    body = []

    for field in fields:
        if isinstance(field, str):
            continue

        if version == '1.0' and hasattr(instance, 'gpx_10_fields') and field not in instance.gpx_10_fields:
            continue
        if version == '1.1' and hasattr(instance, 'gpx_11_fields') and field not in instance.gpx_11_fields:
            continue

        value = getattr(instance, field.name, None)

        if value is None:
            continue

        xml_str = field.to_xml(value, version, nsmap=nsmap, prettyprint=prettyprint, indent=indent + '  ')

        if xml_str:
            if field.attribute:
                attributes.append(xml_str)
            else:
                body.append(xml_str)

    for key, value in custom_attributes.items():
        attributes.append(f'{key}="{value}"')

    if not body and empty_body:
        attr_str = ' '.join(attributes)
        if attr_str:
            return f'\n{indent}<{tag} {attr_str} />'
        else:
            return f'\n{indent}<{tag} />'

    if not body:
        attr_str = ' '.join(attributes)
        if attr_str:
            return f'\n{indent}<{tag} {attr_str} />'
        else:
            return f'\n{indent}<{tag} />'

    attr_str = ' '.join(attributes)
    if attr_str:
        result = f'\n{indent}<{tag} {attr_str}>'
    else:
        result = f'\n{indent}<{tag}>'

    result += ''.join(body)
    result += f'\n{indent}</{tag}>'

    return result


def gpx_fields_from_xml(class_or_instance: Any, node: str, version: str) ->Any:
    if isinstance(class_or_instance, type):
        instance = class_or_instance()
    else:
        instance = class_or_instance

    fields = []
    if hasattr(instance, 'gpx_10_fields'):
        fields.extend(instance.gpx_10_fields)
    if hasattr(instance, 'gpx_11_fields'):
        fields.extend(instance.gpx_11_fields)

    for field in fields:
        if isinstance(field, str):
            continue

        if version == '1.0' and hasattr(instance, 'gpx_10_fields') and field not in instance.gpx_10_fields:
            continue
        if version == '1.1' and hasattr(instance, 'gpx_11_fields') and field not in instance.gpx_11_fields:
            continue

        value = field.from_xml(node, version)

        if value is not None:
            setattr(instance, field.name, value)

    return instance


def from_xml(self, node: Any, version: str) ->Any:
    return gpx_fields_from_xml(self, node, version)


