def parse_time(string: str) ->Optional[mod_datetime.datetime]:
    match = RE_TIMESTAMP.match(string)
    if not match:
        return None

    year, month, day, hour, minute, second, frac, tz = match.groups()

    year = int(year)
    month = int(month)
    day = int(day)
    hour = int(hour)
    minute = int(minute)
    second = int(second)

    microsecond = 0
    if frac:
        frac = frac[1:]
        if len(frac) <= 6:
            microsecond = int(frac.ljust(6, '0'))
        else:
            microsecond = int(frac[:6])
            if len(frac) > 6 and int(frac[6]) >= 5:
                microsecond += 1
            if microsecond >= 1000000:
                microsecond = 999999

    tzinfo = None
    if tz:
        if tz == 'Z':
            tzinfo = SimpleTZ()
        else:
            tzinfo = SimpleTZ(tz)

    return mod_datetime.datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tzinfo)
