def format_time(time: mod_datetime.datetime) ->str:
    if time is None:
        return ''

    # Handle timezone
    if time.tzinfo is None:
        # No timezone, add Z for UTC
        tz_str = 'Z'
    elif isinstance(time.tzinfo, SimpleTZ):
        # Custom timezone
        offset = time.tzinfo.offset
        if offset == 0:
            tz_str = 'Z'
        else:
            hours = offset // 60
            minutes = abs(offset % 60)
            if hours < 0:
                sign = '-'
                hours = -hours
            else:
                sign = '+'
            tz_str = f'{sign}{hours:02d}:{minutes:02d}'
    else:
        # Other timezone types, try to get offset
        offset = time.utcoffset()
        if offset is None:
            tz_str = 'Z'
        else:
            total_minutes = int(offset.total_seconds() // 60)
            if total_minutes == 0:
                tz_str = 'Z'
            else:
                hours = total_minutes // 60
                minutes = abs(total_minutes % 60)
                if hours < 0:
                    sign = '-'
                    hours = -hours
                else:
                    sign = '+'
                tz_str = f'{sign}{hours:02d}:{minutes:02d}'

    # Format the date/time part
    # Always include 6 digits for microseconds, even if zero
    if time.microsecond:
        microsecond_str = f'.{time.microsecond:06d}'
    else:
        microsecond_str = ''

    # Create the basic timestamp
    timestamp = f'{time.year:04d}-{time.month:02d}-{time.day:02d}T{time.hour:02d}:{time.minute:02d}:{time.second:02d}{microsecond_str}{tz_str}'

    return timestamp

def _check_dependents(gpx_object: Any, fieldname: str) ->Tuple[str, str]:
    # Handle conditional metadata tag for GPX 1.0 vs 1.1
    if fieldname == 'metadata':
        # In GPX 1.0, metadata is not supported, so suppress it
        if hasattr(gpx_object, 'version') and gpx_object.version == '1.0':
            return '/metadata', 'metadata'
        # In GPX 1.1, metadata is supported and should be shown
        else:
            return '', 'metadata'

    # Handle bounds - only show when there are actual bounds
    if fieldname == 'bounds':
        if hasattr(gpx_object, 'bounds') and gpx_object.bounds is None:
            return '/bounds', 'bounds'
        else:
            return '', 'bounds'

    # Handle conditional fields for GPX 1.1
    if fieldname == 'name' and hasattr(gpx_object, 'version') and gpx_object.version == '1.1':
        # For GPX 1.1, name should be in metadata when it exists
        if hasattr(gpx_object, 'name') and gpx_object.name is not None:
            return 'name', '/name'

    # Default behavior - don't suppress anything
    return '', fieldname

def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if not prettyprint:
        indent = ''

    result = []

    # Handle custom attributes
    attributes_str = ''
    if custom_attributes:
        attrs = []
        for key, value in custom_attributes.items():
            attrs.append(f'{key}="{value}"')
        attributes_str = ' ' + ' '.join(attrs) if attrs else ''

    # Handle namespace map
    nsmap_str = ''
    if nsmap:
        nsmap_attrs = []
        for prefix, uri in nsmap.items():
            nsmap_attrs.append(f'xmlns:{prefix}="{uri}"')
        nsmap_str = ' ' + ' '.join(nsmap_attrs) if nsmap_attrs else ''

    # Start building the XML
    if empty_body:
        result.append(f'<{tag}{attributes_str}{nsmap_str} />')
        return ''.join(result)

    result.append(f'<{tag}{attributes_str}{nsmap_str}>')

    # Get fields based on version
    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = instance.gpx_11_fields

    # Process each field
    for field in fields:
        if isinstance(field, str):
            # Handle special field names like '/tag' for conditional fields
            # Check if this is a conditional field (starts with /)
            if field.startswith('/'):
                # Skip conditional fields - they're handled by the parent
                continue

            # Handle field names with dependencies (colon separated)
            field_name = field
            if ':' in field:
                field_parts = field.split(':')
                field_name = field_parts[0]
                # Check if all dependencies are empty
                skip_field = False
                for dep in field_parts[1:]:
                    if hasattr(instance, dep):
                        dep_value = getattr(instance, dep)
                        if dep_value is not None and (not isinstance(dep_value, list) or len(dep_value) > 0):
                            skip_field = False
                            break
                        skip_field = True
                    else:
                        skip_field = True
                if skip_field:
                    continue

            # For string fields that aren't conditional, we need to find the actual field
            # This is a simplified approach - in practice, we'd look up the actual field
            continue
        else:
            # This is a proper GPXField object
            value = getattr(instance, field.name, None)
            if value is not None or field.mandatory:
                field_xml = field.to_xml(value, version, nsmap, prettyprint, indent)
                if field_xml:
                    result.append(field_xml)

    # Add extensions if they exist
    if hasattr(instance, 'extensions') and instance.extensions:
        extensions_xml = GPXExtensionsField('extensions').to_xml(
            instance.extensions, version, nsmap, prettyprint, indent
        )
        if extensions_xml:
            result.append(extensions_xml)

    # Close the tag
    result.append(f'</{tag}>')

    return ''.join(result)

