            field_name = field
        else:
            # Complex field
            field_name = field.name

        try:
            if isinstance(field, str):
                # Handle simple field case
                if field_name == 'latitude' or field_name == 'longitude':
                    # These are handled as attributes
                    continue
                # For other simple fields, get from node
                field_node = node.find(field_name)
                if field_node is not None and field_node.text is not None:
                    setattr(instance, field_name, field_node.text)
            else:
                # Handle complex field
                value = field.from_xml(node, version)
                if value is not None:
                    setattr(instance, field_name, value)
        except Exception:
            # Skip fields that can't be processed
            continue

    # Handle bounds
    if hasattr(instance, 'bounds') and hasattr(instance, 'bounds') and instance.bounds:
        bounds_node = node.find('bounds')
        if bounds_node is not None:
            instance.bounds = instance.bounds.from_xml(bounds_node, version)

    # Handle extensions
    if hasattr(instance, 'extensions') and hasattr(instance, 'extensions'):
        extensions_field = GPXExtensionsField('extensions')
        instance.extensions = extensions_field.from_xml(node, version)

