    if not string:
        return None

    # Handle different timestamp formats
    match = RE_TIMESTAMP.match(string.strip())
    if not match:
        return None

    year, month, day, hour, minute, second = map(int, match.groups()[:6])

    # Parse microseconds if present
    microsecond_str = match.group(7)
    microsecond = 0
    if microsecond_str:
        # Remove the leading dot and pad to 6 digits
        microsecond_str = microsecond_str[1:].ljust(6, '0')[:6]
        microsecond = int(microsecond_str)

    # Parse timezone if present
    tz_str = match.group(8)
    tzinfo = None
    if tz_str:
        if tz_str == 'Z':
            tzinfo = mod_datetime.timezone.utc
        else:
            # Handle timezone offset like +01:00 or -0500
            tz_str = tz_str.replace('−', '-')  # Replace Unicode minus with ASCII
