def calculate_max_speed(speeds_and_distances: List[Tuple[float, float]],
    extreemes_percentile: float, ignore_nonstandard_distances: bool
    ) ->Optional[float]:
    if not speeds_and_distances:
        return None

    # Filter out invalid entries
    valid_speeds_and_distances = [(s, d) for s, d in speeds_and_distances if s is not None and d is not None and d > 0]

    if not valid_speeds_and_distances:
        return None

    # Sort by speed
    sorted_speeds = sorted([s for s, d in valid_speeds_and_distances])

    if not sorted_speeds:
        return None

    # Calculate percentile
    if extreemes_percentile <= 0:
        return sorted_speeds[-1]  # Maximum speed
    elif extreemes_percentile >= 100:
        return sorted_speeds[0]  # Minimum speed

    index = int(len(sorted_speeds) * extreemes_percentile / 100.0)
    if index >= len(sorted_speeds):
        index = len(sorted_speeds) - 1

    return sorted_speeds[index]


